<?php
$users = $users ?? [];
$farms = $farms ?? [];
$tasks = $tasks ?? [];
$events = $events ?? [];
$error = $error ?? null;
$success = $success ?? null;
$csrf = htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tareas y calendario | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><header class="admin-header"><div><p class="eyebrow">Planificación</p><h1>Tareas y calendario</h1><p class="setup-copy">Organiza actividades agrícolas, responsables y fechas operativas.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nueva tarea</h2></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="create_task"><label>Título<input name="title" required maxlength="180"></label><label>Descripción<input name="description" maxlength="500"></label><label>Responsable<select name="assigned_to"><option value="">Sin asignar</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>"><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Prioridad<select name="priority"><option value="LOW">Baja</option><option value="NORMAL" selected>Normal</option><option value="HIGH">Alta</option><option value="URGENT">Urgente</option></select></label><label>Fecha límite<input type="date" name="due_date"></label><button class="primary-button" type="submit">Crear tarea</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Nuevo evento</h2></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="create_event"><label>Título<input name="title" required maxlength="180"></label><label>Tipo<input name="event_type" value="GENERAL" maxlength="80"></label><label>Inicio<input type="datetime-local" name="starts_at" required></label><label>Término<input type="datetime-local" name="ends_at"></label><label>Fundo<select name="farm_id"><option value="">Sin fundo</option><?php foreach ($farms as $farm): ?><option value="<?= (int) $farm['id'] ?>"><?= htmlspecialchars($farm['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><button class="primary-button" type="submit">Crear evento</button></form></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Tareas</h2></header><table class="data-table"><thead><tr><th>Título</th><th>Responsable</th><th>Vence</th><th>Prioridad</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($tasks as $task): ?><tr><td><?= htmlspecialchars($task['title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($task['assignee_name'] ?: 'Sin asignar', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($task['due_date'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($task['priority'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($task['status'], ENT_QUOTES, 'UTF-8') ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="update_task"><input type="hidden" name="task_id" value="<?= (int) $task['id'] ?>"><select name="status"><option value="OPEN">Abierta</option><option value="IN_PROGRESS">En curso</option><option value="DONE">Completada</option><option value="CANCELLED">Cancelada</option></select><button class="button-link" type="submit">Guardar</button></form></td></tr><?php endforeach; ?></tbody></table></article><article class="admin-panel"><header class="panel-header"><h2>Calendario</h2></header><table class="data-table"><thead><tr><th>Evento</th><th>Inicio</th><th>Término</th><th>Fundo</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= htmlspecialchars($event['title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($event['starts_at'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($event['ends_at'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($event['farm_name'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?></tbody></table></article></section></main></body></html>
